#include <ranges>
#include <string>
#include <string_view>
#include <vector>

std::vector<std::string> firstLongWords(std::string_view text, std::size_t minLength, std::size_t count)
{
    std::vector<std::string> result{};
    auto words{ text
        | std::views::split(' ')
        | std::views::transform([](auto&& piece) { return std::string_view{ piece.begin(), piece.end() }; })
        | std::views::filter([minLength](std::string_view word) { return word.length() >= minLength; })
        | std::views::take(count) };
    for (std::string_view word : words)
    {
        result.emplace_back(word);
    }
    return result;
}

unitTests:
using Words = std::vector<std::string>;
TEST("long words only") { CHECK_EQ(firstLongWords("the quick brown fox jumps over lazy dogs", 5, 10), (Words{ "quick", "brown", "jumps" })); }
TEST("stops after count") { CHECK_EQ(firstLongWords("alpha beta gamma delta epsilon", 4, 2), (Words{ "alpha", "beta" })); }
TEST("edge cases") { CHECK(firstLongWords("a bb ccc", 4, 5).empty()); CHECK(firstLongWords("anything at all", 1, 0).empty()); CHECK_EQ(firstLongWords("solo", 1, 3), (Words{ "solo" })); }

